using System.Text.Json;
using System.Text.Json.Serialization;
using Server;

namespace BritanniaRenaissance.Content;

/// <summary>
/// The Furnisher shop as data (Configuration/furnishers.json, generated by ShardContent/tools/world-decorating/build_furnishers_config.py from the
/// approved selection and showroom layout; docs/Design-Proposal-3-House-Decoration-Gold-Sink.md). It lists what the Furnisher sells and what a
/// bought piece is made of, where the Furnisher stands, and every display item of the showroom hall. The shard reads it at start and, with the
/// <c>furnishers</c> feature flag on, places the vendor and the hall from it, so a respawned world gets them back without hand work.
/// </summary>
public sealed class FurnishersRules
{
    [JsonPropertyName("schemaVersion")]
    public int SchemaVersion { get; set; }

    [JsonPropertyName("note")]
    public string Note { get; set; } = "";

    /// <summary>Nothing sells for more than this (owner, 2026-10-08).</summary>
    [JsonPropertyName("priceCeiling")]
    public int PriceCeiling { get; set; }

    /// <summary>How many of each piece the shelf holds; it is refilled after every purchase, so the shop never runs out.</summary>
    [JsonPropertyName("stockDepth")]
    public int StockDepth { get; set; }

    [JsonPropertyName("vendor")]
    public FurnisherSpot Vendor { get; set; } = new();

    [JsonPropertyName("hall")]
    public FurnisherHall Hall { get; set; } = new();

    [JsonPropertyName("pieces")]
    public List<FurnisherPiece> Pieces { get; set; } = [];
}

public sealed class FurnisherSpot
{
    [JsonPropertyName("x")]
    public int X { get; set; }

    [JsonPropertyName("y")]
    public int Y { get; set; }

    [JsonPropertyName("z")]
    public int Z { get; set; }

    [JsonPropertyName("direction")]
    public string Direction { get; set; } = "South";
}

public sealed class FurnisherHall
{
    /// <summary>x0, y0, x1, y1 (inclusive) of the hall and its forecourt on Felucca: every managed display item and the vendor lie inside.</summary>
    [JsonPropertyName("bounds")]
    public int[] Bounds { get; set; } = [];

    [JsonPropertyName("items")]
    public List<FurnisherDisplay> Items { get; set; } = [];
}

/// <summary>One graphic of the hall: an inert copy of part of a piece, at an absolute tile.</summary>
public sealed class FurnisherDisplay
{
    [JsonPropertyName("piece")]
    public string Piece { get; set; } = "";

    [JsonPropertyName("id")]
    public int Id { get; set; }

    [JsonPropertyName("x")]
    public int X { get; set; }

    [JsonPropertyName("y")]
    public int Y { get; set; }

    [JsonPropertyName("z")]
    public int Z { get; set; }

    [JsonPropertyName("hue")]
    public int Hue { get; set; }
}

public sealed class FurnisherPiece
{
    public const string KindItem = "item";
    public const string KindDeed = "deed";

    /// <summary>The cosmetic catalog id (CR-... or CN-...): the permanent key of the piece.</summary>
    [JsonPropertyName("id")]
    public string Id { get; set; } = "";

    [JsonPropertyName("name")]
    public string Name { get; set; } = "";

    /// <summary>1 Common, 2 Uncommon, 3 Scarce, 4 Rare, 5 Extremely Rare, 6 Wonder.</summary>
    [JsonPropertyName("rarity")]
    public int Rarity { get; set; }

    [JsonPropertyName("rarityName")]
    public string RarityName { get; set; } = "";

    [JsonPropertyName("collection")]
    public string Collection { get; set; } = "";

    [JsonPropertyName("price")]
    public int Price { get; set; }

    /// <summary>"item": a single graphic sold as the item itself. "deed": several graphics sold as a stock-style addon deed.</summary>
    [JsonPropertyName("kind")]
    public string Kind { get; set; } = KindItem;

    /// <summary>"floor", "rug" or "wall" (a wall piece must be mounted on a wall of the house).</summary>
    [JsonPropertyName("placement")]
    public string Placement { get; set; } = "floor";

    [JsonPropertyName("facings")]
    public List<FurnishingFacing> Facings { get; set; } = [];

    public bool IsDeed => Kind == FurnisherPiece.KindDeed;

    public bool IsWall => Placement == "wall";

    public FurnishingFacing DefaultFacing => Facings[0];
}

public sealed class FurnishingFacing
{
    /// <summary>south, east, north, west or none: the catalog's facing names.</summary>
    [JsonPropertyName("facing")]
    public string Facing { get; set; } = "none";

    [JsonPropertyName("parts")]
    public List<FurnishingPart> Parts { get; set; } = [];
}

public sealed class FurnishingPart
{
    [JsonPropertyName("id")]
    public int Id { get; set; }

    [JsonPropertyName("dx")]
    public int Dx { get; set; }

    [JsonPropertyName("dy")]
    public int Dy { get; set; }

    [JsonPropertyName("dz")]
    public int Dz { get; set; }

    [JsonPropertyName("hue")]
    public int Hue { get; set; }
}

public static class FurnishersConfiguration
{
    public const string RelativePath = "Configuration/furnishers.json";
    public const int MaxGraphic = 0xFFFF;
    public const int MaxStockDepth = 999;

    private static readonly JsonSerializerOptions Options = new()
    {
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true
    };

    private static Dictionary<string, FurnisherPiece> _byId = [];

    public static FurnishersRules? Settings { get; private set; }

    public static FurnishersRules Parse(string json) =>
        JsonSerializer.Deserialize<FurnishersRules>(json, Options) ??
        throw new InvalidOperationException("The furnishers configuration is empty.");

    /// <summary>Reads and validates Configuration/furnishers.json. Always validated, whether or not the feature flag is on, so bad data fails at start.</summary>
    public static void Load()
    {
        var path = Path.Combine(Core.BaseDirectory, RelativePath);

        if (!File.Exists(path))
        {
            throw new InvalidOperationException($"The furnishers configuration is missing: {path}");
        }

        var rules = Parse(File.ReadAllText(path));
        var errors = Validate(rules);

        if (errors.Count > 0)
        {
            throw new InvalidOperationException(
                $"The furnishers configuration failed validation:{Environment.NewLine}- {string.Join(Environment.NewLine + "- ", errors)}"
            );
        }

        Install(rules);
    }

    public static void Install(FurnishersRules rules)
    {
        Settings = rules;
        _byId = rules.Pieces.ToDictionary(p => p.Id);
    }

    public static FurnisherPiece? Find(string? pieceId) =>
        pieceId is not null && _byId.TryGetValue(pieceId, out var piece) ? piece : null;

    /// <summary>The engine direction for a catalog facing name. A piece with no facing ("none") stands South.</summary>
    public static Direction ToDirection(string facing) =>
        facing switch
        {
            "east" => Direction.East,
            "north" => Direction.North,
            "west" => Direction.West,
            _ => Direction.South
        };

    public static bool TryParseDirection(string name, out Direction direction)
    {
        direction = Direction.South;
        return name is "South" or "East" or "North" or "West" && Enum.TryParse(name, out direction);
    }

    public static IReadOnlyList<string> Validate(FurnishersRules rules)
    {
        var errors = new List<string>();

        if (rules.SchemaVersion != 1)
        {
            errors.Add($"schemaVersion must be 1, but was {rules.SchemaVersion}.");
        }

        if (rules.PriceCeiling < 1)
        {
            errors.Add($"priceCeiling must be at least 1, but was {rules.PriceCeiling}.");
        }

        if (rules.StockDepth < 1 || rules.StockDepth > MaxStockDepth)
        {
            errors.Add($"stockDepth must be between 1 and {MaxStockDepth}, but was {rules.StockDepth}.");
        }

        if (rules.Pieces.Count == 0)
        {
            errors.Add("pieces must not be empty.");
        }

        var ids = new HashSet<string>();

        foreach (var piece in rules.Pieces)
        {
            ValidatePiece(piece, rules, ids, errors);
        }

        // The ladder: every rarity costs more than the one below it, so a piece's rarity always reads in its price.
        var byRarity = rules.Pieces.Where(p => p.Rarity is >= 1 and <= 6).GroupBy(p => p.Rarity).OrderBy(g => g.Key).ToList();

        for (var i = 1; i < byRarity.Count; i++)
        {
            var below = byRarity[i - 1];
            var above = byRarity[i];

            if (above.Min(p => p.Price) <= below.Max(p => p.Price))
            {
                errors.Add(
                    $"rarity {above.Key} starts at {above.Min(p => p.Price)} gp, which is not above the dearest rarity {below.Key} piece ({below.Max(p => p.Price)} gp)."
                );
            }
        }

        ValidateHall(rules, errors);
        return errors;
    }

    private static void ValidatePiece(FurnisherPiece piece, FurnishersRules rules, HashSet<string> ids, List<string> errors)
    {
        var where = $"piece {(string.IsNullOrWhiteSpace(piece.Id) ? "(no id)" : piece.Id)}";

        if (string.IsNullOrWhiteSpace(piece.Id) || !ids.Add(piece.Id))
        {
            errors.Add($"{where}: the id is missing or listed twice.");
        }

        if (string.IsNullOrWhiteSpace(piece.Name))
        {
            errors.Add($"{where}: name is missing.");
        }

        if (piece.Rarity is < 1 or > 6)
        {
            errors.Add($"{where}: rarity must be 1 to 6, but was {piece.Rarity}.");
        }

        if (piece.Price < 1 || piece.Price > rules.PriceCeiling)
        {
            errors.Add($"{where}: price must be between 1 and the ceiling {rules.PriceCeiling}, but was {piece.Price}.");
        }

        if (piece.Kind is not (FurnisherPiece.KindItem or FurnisherPiece.KindDeed))
        {
            errors.Add($"{where}: kind must be \"item\" or \"deed\", but was \"{piece.Kind}\".");
        }

        if (piece.Placement is not ("floor" or "rug" or "wall"))
        {
            errors.Add($"{where}: placement must be floor, rug or wall, but was \"{piece.Placement}\".");
        }

        if (piece.Facings.Count == 0)
        {
            errors.Add($"{where}: it needs at least one facing.");
        }

        if (piece.Facings.Count > 1 && piece.Facings.Any(f => f.Facing == "none"))
        {
            errors.Add($"{where}: a piece with several facings cannot also have a facing of none.");
        }

        foreach (var facing in piece.Facings)
        {
            if (facing.Facing is not ("south" or "east" or "north" or "west" or "none"))
            {
                errors.Add($"{where}: facing \"{facing.Facing}\" is not south, east, north, west or none.");
            }

            // A hanging goes on the wall to its north or west (the only walls a house has graphics for), named by the side it is hung on.
            if (piece.Placement == "wall" && facing.Facing is not ("north" or "west"))
            {
                errors.Add($"{where}: a wall piece faces north or west, but has facing {facing.Facing}.");
            }

            if (facing.Parts.Count == 0)
            {
                errors.Add($"{where}: facing {facing.Facing} has no graphics.");
            }

            if (piece.Kind == FurnisherPiece.KindItem && (facing.Parts.Count != 1 || facing.Parts[0] is not { Dx: 0, Dy: 0, Dz: 0 }))
            {
                errors.Add($"{where}: an item has exactly one graphic at no offset in every facing.");
            }

            foreach (var part in facing.Parts)
            {
                if (part.Id < 1 || part.Id > MaxGraphic || part.Hue < 0)
                {
                    errors.Add($"{where}: graphic {part.Id} (hue {part.Hue}) is out of range.");
                }
            }
        }

        if (piece.Facings.Select(f => f.Facing).Distinct().Count() != piece.Facings.Count)
        {
            errors.Add($"{where}: a facing is listed twice.");
        }
    }

    private static void ValidateHall(FurnishersRules rules, List<string> errors)
    {
        var bounds = rules.Hall.Bounds;

        if (bounds.Length != 4 || bounds[0] > bounds[2] || bounds[1] > bounds[3])
        {
            errors.Add("hall.bounds must be x0, y0, x1, y1 with x0 <= x1 and y0 <= y1.");
            return;
        }

        bool Inside(int x, int y) => x >= bounds[0] && x <= bounds[2] && y >= bounds[1] && y <= bounds[3];

        if (!Inside(rules.Vendor.X, rules.Vendor.Y))
        {
            errors.Add($"vendor ({rules.Vendor.X}, {rules.Vendor.Y}) is outside hall.bounds.");
        }

        if (!TryParseDirection(rules.Vendor.Direction, out _))
        {
            errors.Add($"vendor.direction must be South, East, North or West, but was \"{rules.Vendor.Direction}\".");
        }

        var known = rules.Pieces.Select(p => p.Id).ToHashSet();
        var shown = new HashSet<string>();

        foreach (var item in rules.Hall.Items)
        {
            if (!known.Contains(item.Piece))
            {
                errors.Add($"hall item at ({item.X}, {item.Y}) shows {item.Piece}, which is not a piece.");
            }
            else
            {
                shown.Add(item.Piece);
            }

            if (!Inside(item.X, item.Y))
            {
                errors.Add($"hall item {item.Piece} at ({item.X}, {item.Y}) is outside hall.bounds.");
            }

            if (item.Id < 1 || item.Id > MaxGraphic || item.Hue < 0)
            {
                errors.Add($"hall item {item.Piece} has graphic {item.Id} (hue {item.Hue}), which is out of range.");
            }
        }

        foreach (var piece in rules.Pieces.Where(p => !shown.Contains(p.Id)))
        {
            errors.Add($"piece {piece.Id} ({piece.Name}) is not shown anywhere in the hall.");
        }
    }
}
